{
  "findings": [
    {
      "check_id": "CKV_AZURE_129",
      "title": "MySQL server administrator login password is hardcoded",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "CRITICAL",
      "explanation": "The administrator login password for the MySQL server is hardcoded in the Terraform configuration, posing a significant security risk if the code is exposed or accessed by unauthorized parties."
    }
  ],
  "patched_code": "resource \"azurerm_mysql_server\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  storage_mb = \"5120\"\n  sku_name   = \"B_Gen5_1\"\n  version    = \"8.0\"\n  administrator_login          = \"changemeadmin\"\n  administrator_login_password = sensitive(var.mysql_admin_password)\n  ssl_enforcement_enabled = true\n}",
  "fix_summary": "Replaced the hardcoded administrator login password with a reference to a sensitive Terraform variable 'var.mysql_admin_password' to secure the password."
}
